
import VideoPlayer from '../../components/VideoPlayer/page.jsx';
import { useState, useEffect } from "react";
import axios from "axios";


function useVideoSource(apiUrl) {
  const [video, setVideo] = useState({ url: null, tracks: [] });

  useEffect(() => {
    (async () => {
      try {
        const res = await axios.get(apiUrl);
        const { sources: [{ url: videoUrl } = {}] = [], tracks = [] } = res.data;
        setVideo({ url: videoUrl, tracks });
      } catch (err) {
        console.error("Erro ao carregar vídeo:", err);
      }
    })();
  }, [apiUrl]);

  return video;
}

export default function Page() {
  const { url, tracks } = useVideoSource("http://localhost:4000/api/v2/hianime/episode/sources?animeEpisodeId=my-hero-academia-322?ep=6212");

  if (!url) return <p>Carregando vídeo...</p>;

  return <VideoPlayer src={url} subtitles={tracks[0]?.file} />;
}